"use client"

import { ColorSwatchPicker } from "@/registry/preskok/ui/preskok-ui/color-swatch-picker"

export default function ColorSwatchPickerPreskokDemo() {
  const colors = ["#2563eb", "#16a34a", "#ca8a04", "#dc2626", "#9333ea"]
  return (
    <ColorSwatchPicker name="accent" aria-label="Accent color">
      {colors.map((c) => (
        <ColorSwatchPicker.Item key={c} id={c} value={c} />
      ))}
    </ColorSwatchPicker>
  )
}
